/* Real page DOM/events. Native I/O is synthetic; no picker, game or Steam starts. */
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {setup,route,chromium}=require('./experience-ui-tests.cjs');
const tests=[],test=(name,run)=>tests.push({name,run}),shots=path.resolve(__dirname,'../../artifacts/save-environment-ui');
async function fixture(browser,theme='dark'){
 const f=await setup(browser,theme);await f.page.evaluate(()=>{
  const base=chrome.webview.postMessage;
  window.envHeld=[];window.envFx={revision:1,hold:'',cancelNext:false,directory:'D:\\OrangeLauncher快照',chosenDirectory:'E:\\自选快照',changed:false,bindings:{'Sandbox/Test':'snap-old'},saves:[{id:'Sandbox/Test',name:'河畔 · 长期生存'},{id:'Sandbox/Second',name:'罗斯伍德建造'}],snapshots:[{id:'snap-old',name:'第一个冬天',saveId:'Sandbox/Test',gameVersion:'42.20.1',modCount:148,bytes:37458903040,createdUtc:'2026-10-20T07:30:00Z',rootPath:'E:\\Snapshots\\Winter'},{id:'snap-new',name:'河畔 · 当前模组组合',saveId:'Sandbox/Test',gameVersion:'42.21.0',modCount:153,bytes:39858903040,createdUtc:'2026-10-26T07:30:00Z',rootPath:'E:\\Snapshots\\Riverside'},{id:'snap-other',name:'独立建造环境',saveId:'Sandbox/Second',gameVersion:'41.78.16',modCount:12,bytes:18258903040,createdUtc:'2026-10-19T07:30:00Z',rootPath:'E:\\Snapshots\\Builder'}]};
  fx.saves=envFx.saves.map(s=>({...s,mode:'Sandbox',editable:true,modifiedUtc:'2026-10-27T07:30:00Z',modCount:153}));
  const list=id=>{id=id||envFx.saves[0].id;return{stamp:'environment-'+envFx.revision,selectedSaveId:id,selectedSaveName:envFx.saves.find(s=>s.id===id)?.name,activeSnapshotId:envFx.bindings[id]||'',saveBackupSeparate:true,saves:envFx.saves,snapshots:envFx.snapshots.map(s=>({...s,active:envFx.bindings[s.saveId]===s.id})),warnings:[]};};
  window.envReply=m=>{const p=m.payload||{};let data;
   if(m.action==='environmentList')data=list(p.saveId);
   else if(m.action==='environmentPreview')data={stamp:'preview-'+p.saveId+'-'+envFx.revision,bindingStamp:'binding-'+envFx.revision,saveId:p.saveId,gameVersion:'42.21.0',gameBytes:28991029248,modBytes:10867873792,modCount:p.saveId==='Sandbox/Second'?12:153,warnings:envFx.previewWarnings||[],ready:envFx.previewReady!==false,canPrepare:!!envFx.canPrepare,missing:envFx.missing||[]};
   else if(m.action==='environmentStorageGet')data={directory:envFx.directory};
   else if(m.action==='environmentStorageChoose'){if(envFx.cancelStorage){envFx.cancelStorage=false;data={cancelled:true};}else{envFx.directory=envFx.chosenDirectory;data={directory:envFx.directory};}}
   else if(m.action==='environmentPreviewCancel')data={jobId:p.jobId,cancelled:true};
   else if(m.action==='environmentCreateDefault'){if(envFx.cancelNext){envFx.cancelNext=false;data={cancelled:true};}else{const s={id:'snap-created-'+envFx.revision,name:p.name,saveId:p.saveId,gameVersion:'42.21.0',modCount:153,bytes:39858903040,createdUtc:'2026-10-27T10:00:00Z',rootPath:'E:\\Chosen folder\\New environment'};envFx.snapshots.push(s);envFx.bindings[p.saveId]=s.id;envFx.revision++;data={message:'游戏与模组快照已创建',snapshot:s,list:list(p.saveId)};}}
   else if(m.action==='environmentBind'){envFx.bindings[p.saveId]=p.snapshotId;envFx.revision++;data={message:'已使用所选快照',list:list(p.saveId)};}
   else if(m.action==='environmentUnbind'){delete envFx.bindings[p.saveId];envFx.revision++;data={message:'已使用当前环境；历史快照保留',list:list(p.saveId)};}
   else if(m.action==='environmentCheck')data={snapshotId:p.snapshotId,changed:envFx.changed,available:envFx.checkAvailable!==false,message:envFx.checkAvailable===false?'当前原始来源已不可用，快照仍可继续使用。':envFx.changed?'当前游戏和模组原文件已有更新。':'游戏和模组原文件没有变化。',gameChanged:envFx.changed,modsChanged:envFx.changed};
   else if(m.action==='versionList')data={versions:[{id:'v42',name:'当前 Steam 游戏',version:'42.21.0',gamePath:'Fixture Game',userPath:'Original User',selected:true,installed:true}]};
   else if(m.action==='versionInstallState')data={stage:'none'};
   else if(m.action==='backupSettingsGet')data={enabled:false,retention:10,directory:'Synthetic backups'};
   else if(m.action==='worldEditRecovery')data={pending:false};else return base(m);
   emitNative({id:m.id,ok:true,data});
  };
  chrome.webview.postMessage=m=>{if(m.action.startsWith('environment')||['versionList','versionInstallState','backupSettingsGet','worldEditRecovery'].includes(m.action)){sent.push(m);if(envFx.hold===m.action||envFx.holds?.includes(m.action))envHeld.push(m);else queueMicrotask(()=>envReply(m));}else base(m);};
 });return f;
}
async function snapshots(page){await route(page,'versions');await page.locator('[data-environment-tab="snapshots"]').click();await page.locator('[data-environment-card="snap-old"]').waitFor();}
const sent=(p,a)=>p.evaluate(a=>window.sent.filter(m=>m.action===a).map(m=>m.payload),a);
async function review(page){await page.locator('[data-environment-create]').click();await page.locator('#environment-create-dialog [data-environment-choose]').waitFor();await page.waitForFunction(()=>!document.querySelector('[data-environment-choose]').disabled);}
test('versions and save shortcut expose a separate snapshot workspace with real metadata and retained backups',async b=>{
 const {page,errors}=await fixture(b);await snapshots(page);assert.match(await page.locator('#page h1').innerText(),/版本管理.*存档快照/);assert.match(await page.locator('[data-environment-root]').innerText(),/保存此存档使用的游戏版本和模组原文件/);assert.equal(await page.locator('[data-environment-save]').inputValue(),'Sandbox/Test');const row=page.locator('[data-environment-card="snap-old"]');assert.match(await row.innerText(),/42\.20\.1[\s\S]*148[\s\S]*GiB[\s\S]*2026/);assert.match(await row.innerText(),/当前使用/);assert.equal(await page.locator('[data-environment-card="snap-other"]').count(),0);assert.match(await page.locator('[data-environment-root]').innerText(),/原存档|原来的存档/);
 await page.locator('[data-environment-tab="versions"]').click();assert.equal(await page.locator('[data-version-install]').count(),1);await route(page,'saves');await page.locator('[data-environment-open="Sandbox/Test"]').waitFor();assert.equal(await page.locator('[data-save-backups="Sandbox/Test"]').count(),1);await page.locator('[data-environment-open="Sandbox/Test"]').click();await page.locator('[data-environment-card="snap-old"]').waitFor();assert.deepEqual(errors,[]);await page.close();
});
test('create obtains fresh preview, preserves name focus and creates in the remembered directory without a picker',async b=>{
 const {page,errors}=await fixture(b);await snapshots(page);await page.evaluate(()=>envFx.hold='environmentPreview');await page.locator('[data-environment-create]').click();await page.locator('#environment-create-dialog').waitFor();const name=page.locator('#environment-snapshot-name');await name.fill('冬季 <新的环境>');await name.focus();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});await page.waitForFunction(()=>!document.querySelector('[data-environment-choose]').disabled);assert.equal(await name.inputValue(),'冬季 <新的环境>');assert.equal(await name.evaluate(e=>document.activeElement===e),true);assert.match(await page.locator('[data-environment-review]').innerText(),/42\.21\.0[\s\S]*153[\s\S]*GiB/);
 await page.evaluate(()=>{envFx.hold='environmentCreateDefault';});await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.locator('[data-environment-choose]').evaluate(e=>{e.disabled=false;e.click();e.click();});assert.equal((await sent(page,'environmentCreateDefault')).length,1);assert.deepEqual(await sent(page,'environmentCreateDefault'),[{saveId:'Sandbox/Test',name:'冬季 <新的环境>',stamp:'preview-Sandbox/Test-1'}]);await page.evaluate(()=>emitNative({event:'progress',data:{active:true,text:'正在复制游戏原文件…',value:17}}));assert.match(await page.locator('[data-environment-progress-text]').innerText(),/复制游戏原文件/);assert.equal(await page.locator('[data-environment-progress] progress').getAttribute('value'),'17');
 await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});await page.locator('#environment-create-dialog').waitFor({state:'detached'});await page.locator('[data-environment-card="snap-created-1"]').waitFor();assert.equal(await page.locator('[data-environment-card="snap-old"]').count(),1);assert.equal(await page.locator('[data-environment-card="snap-created-1"] script').count(),0);assert.deepEqual(errors,[]);await page.close();
});
test('manifest-save remains in creation with activity and real elapsed time instead of stale copy totals',async b=>{
 fs.mkdirSync(shots,{recursive:true});for(const theme of ['dark','light']){const{page,errors}=await fixture(b,theme);await page.setViewportSize({width:733,height:507});await snapshots(page);await review(page);await page.evaluate(()=>envFx.hold='environmentCreateDefault');await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'copy-mods',text:'正在复制模组文件',value:100,completedFiles:321,totalFiles:321,completedBytes:2147483648,totalBytes:2147483648}}));assert.equal(await page.locator('[data-environment-progress] progress').isVisible(),true);await page.evaluate(()=>emitNative({event:'progress',data:{active:true,text:'正在保存快照文件清单 · 163000 项',value:-1}}));assert.equal(await page.locator('[data-environment-progress] progress').isVisible(),false,'the global phase message must retire the old copy percentage immediately');await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'manifest-save',text:'正在保存快照文件清单 · 163000 项',value:-1,completedFiles:0,totalFiles:0,completedBytes:0,totalBytes:0}}));assert.equal(await page.locator('[data-environment-stage="2"]').evaluate(e=>e.classList.contains('is-current')),true);assert.equal(await page.locator('.environment-progress-stats').isVisible(),false);assert.equal(await page.locator('[data-environment-progress-detail]').isVisible(),false);assert.equal(await page.locator('[data-environment-activity]').isVisible(),true);assert.equal(await page.locator('[data-environment-progress-mode]').innerText(),'保存中');assert.doesNotMatch(await page.locator('[data-environment-progress]').innerText(),/100\s*%|0\s*B|读取本机文件|正在读取文件|JSON/);const before=Number.parseInt(await page.locator('[data-environment-elapsed]').innerText());await page.waitForTimeout(1100);await page.evaluate(()=>pollCallbacks.at(-1)());assert.ok(Number.parseInt(await page.locator('[data-environment-elapsed]').innerText())>=before+1,'elapsed time follows the real clock while saving');await page.locator('[data-environment-progress]').scrollIntoViewIfNeeded();const cancel=await page.locator('[data-environment-cancel-task]').boundingBox();assert.ok(cancel.y>=0&&cancel.y+cancel.height<=507);assert.equal(await page.locator('#environment-create-dialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);await page.screenshot({path:path.join(shots,`${theme}-manifest-save-733.png`),animations:'disabled'});await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'complete',text:'快照已创建',value:100,completedFiles:321,totalFiles:321,completedBytes:2147483648,totalBytes:2147483648}}));assert.equal(await page.locator('.environment-progress-stats').isVisible(),true);await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});await page.locator('#environment-create-dialog').waitFor({state:'detached'});assert.deepEqual(errors,[]);await page.close();}
});
test('snapshot-cleanup shows activity once and restores editable retry after failure or cancellation',async b=>{
 fs.mkdirSync(shots,{recursive:true});for(const scenario of [{theme:'dark',cancelled:false},{theme:'light',cancelled:true}]){const{page,errors}=await fixture(b,scenario.theme);await page.setViewportSize({width:733,height:507});await snapshots(page);await review(page);await page.locator('#environment-snapshot-name').fill('清理后仍可重试');await page.evaluate(()=>envFx.hold='environmentCreateDefault');await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'copy-game',text:'正在复制游戏文件',value:100,completedFiles:321,totalFiles:321,completedBytes:2147483648,totalBytes:2147483648}}));if(scenario.cancelled)await page.locator('[data-environment-cancel-task]').click();await page.evaluate(()=>emitNative({event:'progress',data:{active:true,text:'正在清理未完成的快照',value:-1}}));assert.equal(await page.locator('[data-environment-progress] progress').isVisible(),false);assert.equal(await page.locator('[data-environment-progress-mode]').innerText(),'清理中');await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'snapshot-cleanup',text:'正在清理未完成的快照',value:-1,completedFiles:0,totalFiles:0,completedBytes:0,totalBytes:0}}));assert.equal(await page.locator('.environment-progress-stats').isVisible(),false);assert.equal(await page.locator('[data-environment-progress-detail]').isVisible(),false);assert.equal(await page.locator('[data-environment-stage="2"]').evaluate(e=>e.classList.contains('is-current')),true);assert.equal(await page.locator('[data-environment-cancel-task]').isDisabled(),true);await page.locator('[data-environment-cancel-task]').evaluate(e=>e.click());assert.equal((await sent(page,'cancel')).length,scenario.cancelled?1:0);const before=Number.parseInt(await page.locator('[data-environment-elapsed]').innerText());await page.waitForTimeout(1100);await page.evaluate(()=>pollCallbacks.at(-1)());assert.ok(Number.parseInt(await page.locator('[data-environment-elapsed]').innerText())>=before+1);await page.locator('[data-environment-progress]').scrollIntoViewIfNeeded();assert.doesNotMatch(await page.locator('[data-environment-progress]').innerText(),/100\s*%|0\s*B|正在读取文件|JSON/);await page.screenshot({path:path.join(shots,`${scenario.theme}-snapshot-cleanup-733.png`),animations:'disabled'});await page.evaluate(cancelled=>{const m=envHeld.shift();emitNative(cancelled?{id:m.id,ok:true,data:{cancelled:true}}:{id:m.id,ok:false,error:'复制失败，未完成的快照已清理。'});},scenario.cancelled);await page.waitForFunction(()=>!orange.state.busy&&!document.querySelector('[data-environment-choose]').disabled);assert.equal(await page.locator('#environment-snapshot-name').inputValue(),'清理后仍可重试');assert.equal(await page.locator('[data-environment-progress]').isHidden(),true);if(!scenario.cancelled)assert.match(await page.locator('[data-environment-dialog-error]').innerText(),/已清理/);await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);assert.equal(await page.locator('[data-environment-cancel-task]').isEnabled(),true);await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});await page.locator('#environment-create-dialog').waitFor({state:'detached'});assert.deepEqual(errors,[]);await page.close();}
});
test('manifest-capacity remains a check and reports list entries without payload byte progress',async b=>{
 const{page,errors}=await fixture(b);await snapshots(page);await review(page);await page.evaluate(()=>envFx.hold='environmentCreateDefault');await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'manifest-capacity',text:'正在核对快照文件清单容量',value:-1,completedFiles:163000,totalFiles:0,completedBytes:0,totalBytes:0}}));assert.equal(await page.locator('[data-environment-stage="0"]').evaluate(e=>e.classList.contains('is-current')),true);assert.equal(await page.locator('.environment-progress-stats>div:first-child>span').innerText(),'清单条目');assert.match(await page.locator('[data-environment-file-count]').innerText(),/163,000|163000/);assert.equal(await page.locator('.environment-progress-stats>div:last-child').isVisible(),false);assert.equal(await page.locator('[data-environment-progress] progress').isVisible(),false);assert.match(await page.locator('[data-environment-progress-mode]').innerText(),/核对/);await page.evaluate(()=>emitNative({event:'progress',data:{active:true,text:'文件清单容量核对完成，正在准备复制',value:-1}}));assert.equal(await page.locator('[data-environment-stage="0"]').evaluate(e=>e.classList.contains('is-current')),true);await page.evaluate(()=>emitNative({event:'environmentProgress',data:{saveId:'Sandbox/Test',jobId:null,stage:'copy-game',text:'正在复制游戏文件',value:1,completedFiles:1,totalFiles:321,completedBytes:1,totalBytes:2147483648}}));assert.equal(await page.locator('.environment-progress-stats>div:last-child').isVisible(),true);assert.equal(await page.locator('[data-environment-cancel-task]').isEnabled(),true);await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});await page.locator('#environment-create-dialog').waitFor({state:'detached'});assert.deepEqual(errors,[]);await page.close();
});
test('cancelled folder changes stay editable and closing an in-flight create requests existing cancellation once',async b=>{
 const {page}=await fixture(b);await snapshots(page);await review(page);await page.locator('#environment-snapshot-name').fill('可继续编辑');await page.evaluate(()=>envFx.cancelStorage=true);await page.locator('[data-environment-storage-change]').click();await page.waitForFunction(()=>!document.querySelector('[data-environment-storage-change]').disabled);assert.match(await page.locator('[data-environment-directory]').innerText(),/D:.*OrangeLauncher/);assert.equal((await sent(page,'environmentCreateDefault')).length,0);assert.equal(await page.locator('#environment-snapshot-name').inputValue(),'可继续编辑');assert.equal(await page.locator('[data-environment-card="snap-created-1"]').count(),0);
 await page.evaluate(()=>envFx.hold='environmentCreateDefault');await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.locator('[data-environment-dialog-close]').click();await page.waitForFunction(()=>sent.some(m=>m.action==='cancel'));assert.equal((await sent(page,'cancel')).length,1);await page.evaluate(()=>{const m=envHeld.shift();emitNative({id:m.id,ok:true,data:{cancelled:true}});envFx.hold='';});await page.waitForFunction(()=>!orange.state.busy);assert.equal(await page.locator('#environment-create-dialog').count(),0);assert.equal(await page.locator('[data-environment-card="snap-old"]').count(),1);await page.close();
});
