 await page.locator('[data-environment-bind="snap-new"]').click();await page.waitForFunction(()=>document.querySelector('[data-environment-card="snap-new"] [data-environment-continue]'));await page.locator('[data-environment-continue]').click();await page.waitForFunction(()=>sent.some(m=>m.action==='profileLaunch'));assert.equal((await sent(page,'profileLaunch')).at(-1).id,'Sandbox/Test');assert.equal((await sent(page,'versionSelect')).length,0);assert.equal((await sent(page,'backupCreate')).length,0);assert.deepEqual(errors,[]);await page.close();
