test('old save and game replies cannot replace current snapshots or reopen a closed preview',async b=>{
 const {page,errors}=await fixture(b);await snapshots(page);await page.evaluate(()=>envFx.hold='environmentList');await page.locator('[data-environment-refresh]').click();await page.waitForFunction(()=>envHeld.length===1);await page.locator('[data-environment-save]').selectOption('Sandbox/Second');await page.waitForFunction(()=>envHeld.length===2);await page.evaluate(()=>{const old=envHeld.shift(),next=envHeld.shift();envFx.hold='';envReply(next);envReply(old);});await page.locator('[data-environment-card="snap-other"]').waitFor();assert.equal(await page.locator('[data-environment-card="snap-old"]').count(),0);
 await page.evaluate(()=>envFx.hold='environmentPreview');await page.locator('[data-environment-create]').click();await page.waitForFunction(()=>envHeld.length===1);await page.locator('[data-environment-dialog-close]').click();await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});assert.equal(await page.locator('#environment-create-dialog').count(),0);assert.equal((await sent(page,'environmentCreateDefault')).length,0);
 await page.evaluate(()=>envFx.hold='environmentPreview');await page.locator('[data-environment-create]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>orange.acceptStatus({...orange.state.status,gamePath:'Other game',configStamp:'other-game'}));await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});assert.equal(await page.locator('#environment-create-dialog').count(),0);assert.equal((await sent(page,'environmentCreateDefault')).length,0);assert.deepEqual(errors,[]);await page.close();
});
test('unready preview never opens the picker and a native create failure retains the editable review',async b=>{
 const{page,errors}=await fixture(b);await snapshots(page);await page.evaluate(()=>{envFx.previewReady=false;envFx.previewWarnings=['生存工具包 (SurvivalKit)：未找到对应的工坊项目。'];});await page.locator('[data-environment-create]').click();await page.getByText('生存工具包 (SurvivalKit)：未找到对应的工坊项目。',{exact:true}).waitFor();assert.equal(await page.locator('[data-environment-choose]').isDisabled(),true);assert.equal((await sent(page,'environmentCreateDefault')).length,0);await page.locator('[data-environment-dialog-close]').click();await page.evaluate(()=>{envFx.previewReady=true;envFx.previewWarnings=[];envFx.hold='environmentCreateDefault';});await review(page);await page.locator('#environment-snapshot-name').fill('失败后保留名称');await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>{const m=envHeld.shift();envFx.hold='';emitNative({id:m.id,ok:false,error:'目标空间不足，快照未创建'});});await page.getByText('目标空间不足，快照未创建',{exact:true}).waitFor();assert.equal(await page.locator('#environment-snapshot-name').inputValue(),'失败后保留名称');assert.equal(await page.locator('[data-environment-progress]').isHidden(),true);assert.equal(await page.locator('#environment-snapshot-name').isEnabled(),true);assert.equal(await page.locator('[data-environment-choose]').isEnabled(),true);assert.equal(await page.locator('[data-environment-card="snap-created-1"]').count(),0);assert.deepEqual(errors,[]);await page.close();
});
test('a completed old-game check cannot unlock a new-game check for the same snapshot ID',async b=>{
 const{page,errors}=await fixture(b);await snapshots(page);await page.evaluate(()=>envFx.hold='environmentCheck');await page.locator('[data-environment-check="snap-old"]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>orange.acceptStatus({...orange.state.status,gamePath:'Other game',configStamp:'other-game'}));await page.waitForFunction(()=>!document.querySelector('[data-environment-check="snap-old"]').disabled);await page.locator('[data-environment-check="snap-old"]').click();await page.waitForFunction(()=>envHeld.length===2);await page.evaluate(()=>envReply(envHeld.shift()));assert.equal(await page.locator('[data-environment-check="snap-old"]').isDisabled(),true);assert.equal(await page.locator('[data-environment-card="snap-old"] .environment-check-result').count(),0);await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});await page.waitForFunction(()=>!document.querySelector('[data-environment-check="snap-old"]').disabled);assert.deepEqual(errors,[]);await page.close();
});
test('missing live sources leave frozen snapshot selection and continue actions available',async b=>{
 const{page,errors}=await fixture(b);await snapshots(page);await page.evaluate(()=>envFx.checkAvailable=false);for(const id of ['snap-old','snap-new']){await page.locator(`[data-environment-check="${id}"]`).click();await page.locator(`[data-environment-card="${id}"] .environment-check-result`).waitFor();}await page.evaluate(()=>orange.acceptStatus({...orange.state.status,validGame:false}));assert.equal(await page.locator('[data-environment-continue]').isEnabled(),true);assert.equal(await page.locator('[data-environment-bind="snap-new"]').isEnabled(),true);assert.match(await page.locator('[data-environment-card="snap-old"] .environment-check-result').innerText(),/原始来源已不可用/);await page.locator('[data-environment-continue]').click();await page.waitForFunction(()=>sent.some(m=>m.action==='profileLaunch'));assert.equal((await sent(page,'profileLaunch')).at(-1).id,'Sandbox/Test');assert.equal((await sent(page,'environmentCreateDefault')).length,0);assert.deepEqual(errors,[]);await page.close();
});
test('desktop and 733px snapshot layouts keep long metadata and review controls within view under reduced motion',async b=>{
 fs.mkdirSync(shots,{recursive:true});for(const theme of ['dark','light']){const{page,errors}=await fixture(b,theme);await page.emulateMedia({reducedMotion:'reduce'});await page.evaluate(()=>envFx.snapshots[0].name='冬季长期生存 · 保存游戏与模组原文件的独立环境 '.repeat(4));await snapshots(page);for(const size of [{width:1366,height:900},{width:733,height:507}]){await page.setViewportSize(size);await page.screenshot({path:path.join(shots,`${theme}-snapshots-${size.width}.png`)});assert.equal(await page.evaluate(()=>document.querySelector('main').scrollWidth>document.querySelector('main').clientWidth),false);await review(page);await page.locator('[data-environment-choose]').scrollIntoViewIfNeeded();const unobscured=await page.locator('.environment-space-total dd').evaluate(e=>{const r=e.getBoundingClientRect();return document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)===e;});assert.equal(unobscured,true,'the review total must remain readable above the choose-folder action');await page.screenshot({path:path.join(shots,`${theme}-review-${size.width}.png`)});const box=await page.locator('#environment-create-dialog').boundingBox();assert.ok(box.x>=0&&box.x+box.width<=size.width+1);assert.equal(await page.locator('#environment-create-dialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);await page.locator('[data-environment-dialog-close]').click();}assert.deepEqual(errors,[]);await page.close();}
});
test('preview shows live scoped progress immediately and closing cancels only that preview',async b=>{
 const{page,errors}=await fixture(b);await snapshots(page);await page.evaluate(()=>envFx.hold='environmentPreview');await page.locator('[data-environment-create]').click();await page.waitForFunction(()=>envHeld.length===1);
 assert.equal(await page.locator('[data-environment-progress]').isVisible(),true);assert.equal(await page.locator('[data-environment-progress] progress').getAttribute('value'),null);
 const request=(await sent(page,'environmentPreview'))[0];assert.match(request.jobId,/^[a-f0-9]{32}$/);
 await page.evaluate(p=>emitNative({event:'environmentProgress',data:{jobId:p.jobId,saveId:p.saveId,stage:'game-inventory',text:'正在统计游戏文件',value:-1,completedFiles:1234,totalFiles:0,completedBytes:2147483648,totalBytes:0}}),request);
 assert.match(await page.locator('[data-environment-progress-text]').innerText(),/正在统计游戏文件/);assert.match(await page.locator('[data-environment-progress-detail]').innerText(),/1,234|1234/);assert.match(await page.locator('[data-environment-progress-detail]').innerText(),/2\.0 GiB/);
 await page.evaluate(p=>emitNative({event:'environmentProgress',data:{jobId:'f'.repeat(32),saveId:p.saveId,text:'上一个任务的过期进度',value:100}}),request);assert.doesNotMatch(await page.locator('[data-environment-progress-text]').innerText(),/过期进度/);
 await page.locator('[data-environment-dialog-close]').click();await page.waitForFunction(()=>sent.some(m=>m.action==='environmentPreviewCancel'));assert.deepEqual(await sent(page,'environmentPreviewCancel'),[{jobId:request.jobId}]);assert.equal((await sent(page,'cancel')).length,0);await page.evaluate(()=>{envFx.hold='';envReply(envHeld.shift());});assert.equal(await page.locator('#environment-create-dialog').count(),0);assert.deepEqual(errors,[]);await page.close();
});
