test('remembered location and optional Workshop retry fields remain readable in both themes and narrow windows',async b=>{
 fs.mkdirSync(shots,{recursive:true});for(const theme of ['dark','light'])for(const size of [{width:1366,height:900},{width:733,height:507}]){const{page,errors}=await fixture(b,theme);await page.setViewportSize(size);await page.emulateMedia({reducedMotion:'reduce'});await snapshots(page);await page.evaluate(()=>{envFx.directory='D:\\OrangeLauncher快照\\长期生存世界与模组存储位置\\需要保持完整的目录名称';envFx.previewReady=false;envFx.canPrepare=true;envFx.missing=[{modId:'UnknownOne',name:'旧存档使用的长期生存翻译模组 · 原作者的完整模组名称',canSearch:true},{modId:'UnknownTwo',name:'第二个需要指定工坊来源的模组',canSearch:true}];});await review(page);assert.equal(await page.locator('[data-environment-directory]').getAttribute('title'),await page.evaluate(()=>envFx.directory));await page.locator('[data-environment-storage-change]').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(shots,`${theme}-remembered-location-${size.width}.png`),animations:'disabled'});await page.locator('[data-environment-workshop-sources]>summary').click();await page.locator('[data-environment-workshop-source="UnknownOne"]').fill('https://steamcommunity.com/sharedfiles/filedetails/?id=3809306528');await page.locator('[data-environment-workshop-source="UnknownTwo"]').fill('3619862853');await page.evaluate(()=>envFx.hold='environmentCreateDefault');await page.locator('[data-environment-choose]').click();await page.waitForFunction(()=>envHeld.length===1);await page.evaluate(()=>{const m=envHeld.shift();emitNative({id:m.id,ok:false,error:'UnknownOne 找到多个工坊结果，请填写对应来源后重试。'});envFx.hold='';});await page.waitForFunction(()=>!document.querySelector('[data-environment-choose]').disabled);await page.locator('[data-environment-choose]').scrollIntoViewIfNeeded();assert.equal(await page.locator('#environment-create-dialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);const button=await page.locator('[data-environment-choose]').boundingBox();assert.ok(button.y>=0&&button.y+button.height<=size.height);assert.equal(await page.locator('[data-environment-workshop-sources]').getAttribute('open'),'');await page.screenshot({path:path.join(shots,`${theme}-workshop-retry-${size.width}.png`),animations:'disabled'});assert.deepEqual(errors,[]);await page.close();}
});
test('live progress and missing-mod review stay readable at desktop and narrow sizes',async b=>{
 fs.mkdirSync(shots,{recursive:true});for(const theme of ['dark','light'])for(const size of [{width:1366,height:900},{width:733,height:507}]){
  const{page,errors}=await fixture(b,theme);await page.setViewportSize(size);await snapshots(page);await page.evaluate(()=>envFx.hold='environmentPreview');await page.locator('[data-environment-create]').click();await page.waitForFunction(()=>envHeld.length===1);const job=(await sent(page,'environmentPreview'))[0];
  await page.evaluate(p=>emitNative({event:'environmentProgress',data:{jobId:p.jobId,saveId:p.saveId,stage:'game-inventory',text:'正在统计游戏文件',value:-1,completedFiles:128492,completedBytes:22441170534,totalFiles:0,totalBytes:0}}),job);await page.locator('[data-environment-progress]').scrollIntoViewIfNeeded();
  const bounds=await page.locator('[data-environment-progress]').evaluate(panel=>{const header=panel.querySelector('.environment-progress-header').getBoundingClientRect(),activity=panel.querySelector('[data-environment-activity]').getBoundingClientRect(),stats=panel.querySelector('.environment-progress-stats').getBoundingClientRect();return{headerEnd:header.bottom,statsTop:stats.top,statsEnd:stats.bottom,activityTop:activity.top,overflow:panel.scrollWidth>panel.clientWidth};});assert.ok(bounds.headerEnd<=bounds.statsTop&&bounds.statsEnd<=bounds.activityTop,'actual counters and unknown-total activity must occupy separate readable rows');assert.equal(await page.locator('[data-environment-progress] progress').isVisible(),false,'unknown totals must not imply a percentage');assert.equal(bounds.overflow,false);await page.screenshot({path:path.join(shots,`${theme}-live-check-${size.width}.png`)});
  await page.evaluate(()=>{envFx.previewReady=false;envFx.canPrepare=true;envFx.missing=[{modId:'Viewpoint',name:'Viewpoint 基础视角与生存模组组合 · '+ '长期存档'.repeat(5),canDownload:true}];envFx.hold='';envReply(envHeld.shift());});await page.waitForFunction(()=>!document.querySelector('[data-environment-choose]').disabled);await page.locator('[data-environment-choose]').scrollIntoViewIfNeeded();assert.equal(await page.locator('#environment-create-dialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);await page.screenshot({path:path.join(shots,`${theme}-missing-mods-${size.width}.png`)});await page.locator('[data-environment-dialog-close]').click();assert.deepEqual(errors,[]);await page.close();
 }
});
(async()=>{const selected=tests.filter(t=>!process.env.ORANGE_TEST_FILTER||t.name.includes(process.env.ORANGE_TEST_FILTER));const browser=await chromium.launch({channel:process.env.ORANGE_BROWSER_CHANNEL||'msedge',headless:true});let failed=0;try{for(const t of selected){try{await t.run(browser);console.log('PASS '+t.name);}catch(e){failed++;console.error('FAIL '+t.name+'\n'+e.stack);}}}finally{await browser.close();}console.log(`${selected.length-failed}/${selected.length} snapshot UI groups passed`);if(failed)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1;});
